#!/bin/bash## Emind AI 瀹屾暣璁粌绠＄嚎# 钂搁 鈫?SFT 鈫?DPO 鈫?GRPO 鍏ㄦ祦绋?## 鐢ㄦ硶:#   ./run_full_pipeline.sh#   ./run_full_pipeline.sh --base-model ./models/emind-base#   ./run_full_pipeline.sh --lr 2e-5 --epochs 3## 鍓嶇疆鏉′欢:#   - Python 3.10+#   - PyTorch 2.0+  (CUDA)#   - pip install torch transformers datasets accelerate#   - 鏈夋晥鐨?DeepSeek API Key (EMIND_API_KEY)#   - 鍩哄骇妯″瀷妫€鏌ョ偣 (瑙?--base-model)set -eSCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"cd "$SCRIPT_DIR"# 鈹€鈹€鈹€ 榛樿鍙傛暟 鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€BASE_MODEL="./models/emind-base"OUTPUT_DIR="./checkpoints/emind_full_pipeline"DISTILL_DIR="./data/distilled/emind_code_4b"# 钂搁鍙傛暟 (鍙傝 run_distill.sh)DISTILL_CODE=3000DISTILL_REASONING=500DISTILL_DEEP_REASONING=1000DISTILL_ANTI_HALLUCINATION=1500DISTILL_IDENTITY=100# SFT 鍙傛暟SFT_LR=2e-5SFT_EPOCHS=3SFT_BATCH=4SFT_GRAD_ACC=4# DPO 鍙傛暟DPO_LR=1e-5DPO_EPOCHS=2DPO_BATCH=2DPO_BETA=0.1# GRPO 鍙傛暟GRPO_LR=1e-6GRPO_STEPS=200GRPO_GROUP=8GRPO_BATCH=2# Teacher APIAPI_KEY="${EMIND_API_KEY:-}"TEACHER_MODEL="deepseek-v4-flash"SKIP_DISTILL=false# 鈹€鈹€鈹€ 鍙傛暟瑙ｆ瀽 鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€while [ $# -gt 0 ]; do    case "$1" in        --base-model) BASE_MODEL="$2"; shift 2 ;;        --output) OUTPUT_DIR="$2"; shift 2 ;;        --distill-dir) DISTILL_DIR="$2"; shift 2 ;;        --api-key) API_KEY="$2"; shift 2 ;;        --skip-distill) SKIP_DISTILL=true; shift ;;        --lr) SFT_LR="$2"; shift 2 ;;        --epochs) SFT_EPOCHS="$2"; shift 2 ;;        --help|-h)            echo "鐢ㄦ硶: $0 [閫夐」]"            echo "  --base-model PATH   鍩哄骇妯″瀷璺緞 (榛樿: ./models/emind-base)"            echo "  --output DIR        杈撳嚭鐩綍 (榛樿: ./checkpoints/emind_full_pipeline)"            echo "  --distill-dir DIR   钂搁鏁版嵁鐩綍 (榛樿: ./data/distilled/emind_code_4b)"            echo "  --api-key KEY       DeepSeek API Key"            echo "  --skip-distill      璺宠繃钂搁闃舵锛岀洿鎺ヨ缁?            echo "  --lr NUM           SFT 瀛︿範鐜?(榛樿: 2e-5)"            echo "  --epochs NUM       SFT epoch 鏁?(榛樿: 3)"            exit 0            ;;        *) echo "鏈煡鍙傛暟: $1"; exit 1 ;;    esacdone# 鈹€鈹€鈹€ 1. 鏁版嵁钂搁 鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€if [ "$SKIP_DISTILL" = false ]; then    if [ -z "$API_KEY" ]; then        echo "閿欒: 钂搁闇€瑕?API Key"        echo "璇烽€氳繃 --api-key 鍙傛暟鎴?EMIND_API_KEY 鐜鍙橀噺璁剧疆"        exit 1    fi    echo ""    echo "鈺斺晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺?    echo "鈺? 姝ラ 1/4: 鏁版嵁钂搁                        鈺?    echo "鈺氣晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺?    echo ""    python -u cli.py pipeline \        --distill-code "$DISTILL_CODE" \        --distill-reasoning "$DISTILL_REASONING" \        --distill-deep-reasoning "$DISTILL_DEEP_REASONING" \        --distill-anti-hallucination "$DISTILL_ANTI_HALLUCINATION" \        --distill-identity "$DISTILL_IDENTITY" \        --teacher-backend cloud_api \        --teacher-api-key "$API_KEY" \        --teacher-model "$TEACHER_MODEL" \        --teacher-base-url "https://api.deepseek.com" \        --distill-output "$DISTILL_DIR"    echo ""    echo "鉁?钂搁瀹屾垚"else    echo "璺宠繃钂搁闃舵锛屼娇鐢ㄥ凡鏈夋暟鎹? $DISTILL_DIR"fi# 鈹€鈹€鈹€ 2. SFT 璁粌 鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€echo ""echo "鈺斺晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺?echo "鈺? 姝ラ 2/4: SFT 鐩戠潱寰皟                    鈺?echo "鈺氣晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺?echo ""SFT_OUTPUT="$OUTPUT_DIR/sft"python -u cli.py train \    --mode sft \    --model "$BASE_MODEL" \    --data "$DISTILL_DIR/distilled_sft.jsonl" \    --output "$SFT_OUTPUT" \    --lr "$SFT_LR" \    --epochs "$SFT_EPOCHS" \    --batch-size "$SFT_BATCH" \    --gradient-accumulation "$SFT_GRAD_ACC" \    --fp16echo ""echo "鉁?SFT 瀹屾垚"# 鈹€鈹€鈹€ 3. DPO 鍋忓ソ瀵归綈 鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€echo ""echo "鈺斺晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺?echo "鈺? 姝ラ 3/4: DPO 鍋忓ソ浼樺寲                    鈺?echo "鈺氣晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺?echo ""DPO_OUTPUT="$OUTPUT_DIR/dpo"python -u cli.py train \    --mode dpo \    --model "$SFT_OUTPUT" \    --data "$DISTILL_DIR" \    --output "$DPO_OUTPUT" \    --lr "$DPO_LR" \    --epochs "$DPO_EPOCHS" \    --batch-size "$DPO_BATCH" \    --beta "$DPO_BETA" \    --fp16echo ""echo "鉁?DPO 瀹屾垚"# 鈹€鈹€鈹€ 4. GRPO 寮哄寲瀛︿範 鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€echo ""echo "鈺斺晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺?echo "鈺? 姝ラ 4/4: GRPO 寮哄寲瀛︿範                   鈺?echo "鈺氣晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺?echo ""GRPO_OUTPUT="$OUTPUT_DIR/grpo"python -u cli.py rl \    --mode grpo \    --model "$DPO_OUTPUT" \    --output "$GRPO_OUTPUT" \    --lr "$GRPO_LR" \    --train-steps "$GRPO_STEPS" \    --group-size "$GRPO_GROUP" \    --batch-size "$GRPO_BATCH" \    --fp16echo ""echo "鈺斺晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺?echo "鈺? 鍏ㄩ儴瀹屾垚锛?                               鈺?echo "鈺氣晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺?echo ""echo "鏈€缁堟ā鍨? $GRPO_OUTPUT"echo "涓棿浜х墿:"echo "  SFT:   $SFT_OUTPUT"echo "  DPO:   $DPO_OUTPUT"echo "  GRPO:  $GRPO_OUTPUT"echo ""echo "鎺ㄧ悊娴嬭瘯:"echo "  python cli.py infer --model $GRPO_OUTPUT --prompt '浣犲ソ'"echo "  python cli.py serve --model $GRPO_OUTPUT --port 3333"